// Decides which client gets a post-service message right now. Pure logic: reads the sheets, writes nothing.
// Decide a qué clienta le toca un mensaje post-servicio ahora. Solo lee las hojas, no escribe nada.
//   asistio    → gracias (thank you + rating 1-5) → recordatorio_nota once if she stays silent
//   no_asistio → te_extranamos (we missed you, want to rebook?) once
//   WhatsApp failed (send error or Twilio status callback) → same message once by email, if she has one
//   WhatsApp fallido (error al enviar o status callback) → el mismo mensaje una vez por email, si tiene
// Sent messages live in Seguimientos (origen = P34, cita_id, paso). Ratings live in Calificaciones.
// Los mensajes enviados viven en Seguimientos (origen = P34, cita_id, paso). Las notas, en Calificaciones.

// ⚙️ CONFIG — DEMO_MODE: minutes instead of hours (live demo). false = production times.
// ⚙️ CONFIG — DEMO_MODE: minutos en vez de horas (demo en vivo). false = tiempos de producción.
const DEMO_MODE = true;
const AFTER_END_MIN = DEMO_MODE ? 2 : 2 * 60;        // thank-you / no-show message after the appointment ends
const REMINDER_MIN  = DEMO_MODE ? 5 : 24 * 60;       // rating reminder after the thank-you if she stays silent
const MAX_AGE_MIN   = DEMO_MODE ? 24 * 60 : 3 * 24 * 60; // older appointments are ignored (e.g. marked weeks later)
const SEND_HOURS = [9, 20];                          // production only / solo producción (hora del spa)
const MAX_PER_RUN = 20;
const ACTIVE = ['agendada', 'confirmada', 'reprogramada'];
const FAILED = ['failed', 'undelivered', 'error'];

// --- Sheets → rows (same order as the batchGet URL) / Hojas → filas (mismo orden que la URL)
const SHEETS = ['Leads', 'Citas', 'Seguimientos', 'Calificaciones', 'Conversaciones', 'Escalamientos', 'Negocio', 'Servicios'];
const ranges = $input.first().json.valueRanges || [];
const toRows = (vr) => {
  const v = (vr && vr.values) || [];
  const h = v[0] || [];
  return v.slice(1)
    .map((r, i) => { const o = { row_number: i + 2 }; h.forEach((k, j) => { o[k] = r[j] === undefined ? '' : String(r[j]); }); return o; })
    .filter(o => h.some(k => o[k] !== ''));
};
const t = {};
SHEETS.forEach((s, i) => { t[s] = toRows(ranges[i]); });
const negocio = {};
t.Negocio.forEach(r => { if (r.clave) negocio[r.clave] = r.valor; });

const tz = negocio.zona_horaria || 'America/Phoenix';
const now = $now.setZone(tz);
const parse = s => {
  const str = String(s || '').trim();
  for (const f of ['yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm']) {
    const d = DateTime.fromFormat(str, f, { zone: tz });
    if (d.isValid) return d;
  }
  return null;
};
const fmt = d => (d ? d.toFormat('yyyy-MM-dd HH:mm:ss') : '');
const servicioEn = {};
t.Servicios.forEach(r => { if (r.nombre_es) servicioEn[r.nombre_es] = r.nombre_en || r.nombre_es; });
const leads = {};
t.Leads.forEach(l => { leads[l.lead_id] = l; });

const inHours = DEMO_MODE || (now.hour >= SEND_HOURS[0] && now.hour < SEND_HOURS[1]);

const due = [];
const report = [];   // why each appointment was / was not picked / por qué se eligió o no cada cita
for (const cita of t.Citas) {
  const why = (motivo, extra = {}) => report.push({ cita_id: cita.cita_id, estado: cita.estado, motivo, ...extra });
  if (!['asistio', 'no_asistio'].includes(cita.estado)) { why('estado_no_aplica'); continue; }

  const fin = parse(cita.fin) || parse(cita.inicio);
  if (!fin) { why('fin_invalido'); continue; }
  const minsSinceEnd = now.diff(fin, 'minutes').minutes;
  if (minsSinceEnd < AFTER_END_MIN) { why('aun_no', { cuando: fmt(fin.plus({ minutes: AFTER_END_MIN })) }); continue; }

  const lead = leads[cita.lead_id];
  if (!lead) { why('lead_no_existe'); continue; }
  if (lead.estado === 'opt_out') { why('opt_out'); continue; }
  const whatsapp = cita.whatsapp || lead.whatsapp;
  if (!whatsapp) { why('sin_whatsapp'); continue; }
  // An open case means a person is handling her: the system stays quiet. / Caso abierto = la atiende una persona: silencio.
  if (t.Escalamientos.some(e => e.lead_id === cita.lead_id && e.estado === 'abierto')) { why('escalamiento_abierto'); continue; }

  const sent = t.Seguimientos.filter(s => s.origen === 'P34' && s.cita_id === cita.cita_id);
  const sentWa = p => sent.find(s => s.paso === p && s.canal !== 'email');
  const sentEmail = p => sent.find(s => s.paso === p && s.canal === 'email');
  const failed = s => {
    const conv = s.message_id ? t.Conversaciones.find(m => m.wa_message_sid === s.message_id) : null;
    const estado = String((conv && conv.estado_entrega) || s.resultado || '').toLowerCase();
    return FAILED.some(f => estado.startsWith(f));
  };
  const hasEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(lead.email || '').trim());
  // pendiente | enviado_wa | enviado_email | toca_email | fallido_sin_email
  const stepState = p => {
    const wa = sentWa(p);
    if (!wa) return 'pendiente';
    if (!failed(wa)) return 'enviado_wa';
    if (sentEmail(p)) return 'enviado_email';
    return hasEmail ? 'toca_email' : 'fallido_sin_email';
  };

  let paso = null;
  let canal = 'whatsapp';
  if (cita.estado === 'no_asistio') {
    const st = stepState('te_extranamos');
    if (st !== 'pendiente' && st !== 'toca_email') { why(st === 'fallido_sin_email' ? 'whatsapp_fallido' : 'ya_enviado', { paso: 'te_extranamos' }); continue; }
    // Already rebooked → nothing to recover. / Ya reagendó → nada que recuperar.
    if (t.Citas.some(c => c.lead_id === cita.lead_id && c.cita_id !== cita.cita_id && ACTIVE.includes(c.estado))) { why('ya_reagendo'); continue; }
    if (st === 'pendiente' && minsSinceEnd > MAX_AGE_MIN) { why('muy_vieja'); continue; }
    paso = 'te_extranamos';
    if (st === 'toca_email') canal = 'email';
  } else {
    if (t.Calificaciones.some(c => c.cita_id === cita.cita_id)) { why('ya_califico'); continue; }
    const st = stepState('gracias');
    if (st === 'pendiente' || st === 'toca_email') {
      if (st === 'pendiente' && minsSinceEnd > MAX_AGE_MIN) { why('muy_vieja'); continue; }
      paso = 'gracias';
      if (st === 'toca_email') canal = 'email';
    } else if (st === 'fallido_sin_email') { why('whatsapp_fallido', { paso: 'gracias' }); continue; }
    else if (st === 'enviado_email') { why('gracias_por_email'); continue; }   // no reminder by email / sin recordatorio por email
    else {
      const gracias = sentWa('gracias');
      if (sentWa('recordatorio_nota')) { why('ya_enviado', { paso: 'recordatorio_nota' }); continue; }
      const graciasAt = parse(gracias.fecha);
      if (!graciasAt) { why('fecha_gracias_invalida'); continue; }
      // She wrote after the thank-you → Sofía is talking with her; no reminder. / Escribió después → la atiende Sofía.
      const replied = t.Conversaciones.some(m => m.lead_id === cita.lead_id && m.rol === 'user' && (parse(m.fecha) || graciasAt) > graciasAt);
      if (replied) { why('respondio'); continue; }
      const remindAt = graciasAt.plus({ minutes: REMINDER_MIN });
      if (now < remindAt) { why('aun_no', { paso: 'recordatorio_nota', cuando: fmt(remindAt) }); continue; }
      paso = 'recordatorio_nota';
    }
  }
  if (!inHours) { why('fuera_de_horario', { paso }); continue; }

  due.push({
    cita_id: cita.cita_id, lead_id: cita.lead_id, nombre: cita.nombre || lead.nombre, whatsapp,
    idioma: lead.idioma || 'es', servicio: cita.servicio, servicio_en: servicioEn[cita.servicio] || cita.servicio,
    email: lead.email || '', inicio: cita.inicio, fin: cita.fin, estado_cita: cita.estado, paso, canal,
    secuencia: cita.estado === 'no_asistio' ? 'no_show' : 'post_servicio', ronda: cita.inicio, plantilla: paso
  });
  why('toca', { paso, canal });
}

const picked = due.slice(0, MAX_PER_RUN);
return picked.length
  ? picked.map(d => ({ json: { ...d, demo_mode: DEMO_MODE, ahora: fmt(now), negocio } }))
  : [{ json: { nada: true, ahora: fmt(now), demo_mode: DEMO_MODE, report } }];

// Fills the fixed post-service template (Meta template style: fixed text + variables). No AI: $0 per message.
// Llena la plantilla fija post-servicio (estilo plantilla de Meta: texto fijo + variables). Sin IA: $0 por mensaje.
// Templates / Plantillas: gracias (thank you + 1-5 rating) · recordatorio_nota (one nudge) · te_extranamos (no-show, rebook)
// WhatsApp → input for P31e - Lumière Send WhatsApp. Email (fallback) → input for P32c - Lumière Send Email.
// "Consulta + …" → "consulta + …" mid-sentence; brand names with inner capitals ("HydraFacial") stay as they are
const lower = s => { const w = String(s || '').split(/\s/)[0]; return w.length > 1 && w.slice(1) === w.slice(1).toLowerCase() ? s[0].toLowerCase() + s.slice(1) : s; };
const WA = {
  es: {
    gracias: v => `Hola ${v.nombre} 💛 Gracias por confiar en ${v.spa} ${v.hoy ? 'hoy ' : ''}para tu ${lower(v.servicio)}. Esperamos que te hayas sentido muy bien atendida.\n\n¿Cómo te fue? Respóndenos con un número del *1 al 5* (5 = excelente). Tu opinión nos ayuda a cuidarte mejor.\n\nResponde STOP si no quieres recibir más mensajes.`,
    recordatorio_nota: v => `Hola ${v.nombre}, una pregunta rápida 😊 Del *1 al 5*, ¿cómo calificarías tu ${lower(v.servicio)} en ${v.spa}? Leemos cada respuesta.`,
    te_extranamos: v => `Hola ${v.nombre}, te extrañamos ${v.hoy ? 'hoy ' : ''}en ${v.spa} 💛 Sabemos que a veces surgen imprevistos. ¿Quieres que te busque otro horario para tu ${lower(v.servicio)}? Respóndeme por aquí y lo agendamos en un momento.\n\nResponde STOP si no quieres recibir más mensajes.`
  },
  en: {
    gracias: v => `Hi ${v.nombre} 💛 Thank you for trusting ${v.spa} ${v.hoy ? 'today ' : ''}for your ${lower(v.servicio)}. We hope you felt well taken care of.\n\nHow did it go? Reply with a number from *1 to 5* (5 = excellent). Your feedback helps us take better care of you.\n\nReply STOP to opt out.`,
    recordatorio_nota: v => `Hi ${v.nombre}, quick question 😊 From *1 to 5*, how would you rate your ${lower(v.servicio)} at ${v.spa}? We read every reply.`,
    te_extranamos: v => `Hi ${v.nombre}, we missed you ${v.hoy ? 'today ' : ''}at ${v.spa} 💛 We know things come up. Would you like me to find you another time for your ${lower(v.servicio)}? Just reply here and we'll book it in a moment.\n\nReply STOP to opt out.`
  }
};
// Email fallback (paragraphs split by a blank line; P32c adds logo, WhatsApp button, signature and unsubscribe footer)
// Respaldo por email (párrafos separados por línea en blanco; P32c pone logo, botón a WhatsApp, firma y pie de baja)
const EMAIL = {
  es: {
    gracias: v => ({ asunto: `Gracias por visitarnos, ${v.nombre}`, cta: 'Calificar por WhatsApp',
      mensaje: `Hola ${v.nombre},\n\nGracias por confiar en ${v.spa} para tu ${lower(v.servicio)}. Esperamos que te hayas sentido muy bien atendida.\n\n¿Cómo te fue? Escríbenos por WhatsApp un número del 1 al 5 (5 = excelente). Tu opinión nos ayuda a cuidarte mejor.` }),
    te_extranamos: v => ({ asunto: `Te extrañamos en ${v.spa}`, cta: 'Reagendar por WhatsApp',
      mensaje: `Hola ${v.nombre},\n\nTe extrañamos en tu cita de ${lower(v.servicio)}. Sabemos que a veces surgen imprevistos.\n\nSi quieres, escríbenos por WhatsApp y te buscamos otro horario en un momento.` })
  },
  en: {
    gracias: v => ({ asunto: `Thank you for visiting us, ${v.nombre}`, cta: 'Rate us on WhatsApp',
      mensaje: `Hi ${v.nombre},\n\nThank you for trusting ${v.spa} for your ${lower(v.servicio)}. We hope you felt well taken care of.\n\nHow did it go? Message us on WhatsApp with a number from 1 to 5 (5 = excellent). Your feedback helps us take better care of you.` }),
    te_extranamos: v => ({ asunto: `We missed you at ${v.spa}`, cta: 'Rebook on WhatsApp',
      mensaje: `Hi ${v.nombre},\n\nWe missed you at your ${lower(v.servicio)} appointment. We know things come up.\n\nIf you'd like, message us on WhatsApp and we'll find you another time in a moment.` })
  }
};

return $input.all().map(item => {
  const r = item.json;
  const n = r.negocio || {};
  const lang = String(r.idioma).toLowerCase().startsWith('en') ? 'en' : 'es';
  const tz = n.zona_horaria || 'America/Phoenix';
  const inicio = DateTime.fromFormat(String(r.inicio).slice(0, 16), 'yyyy-MM-dd HH:mm', { zone: tz });
  const v = {
    nombre: String(r.nombre || '').trim().split(/\s+/)[0] || (lang === 'es' ? 'hola' : 'there'),
    spa: n.nombre || 'Lumière Aesthetics',
    servicio: lang === 'en' ? (r.servicio_en || r.servicio) : r.servicio,
    hoy: inicio.isValid && inicio.hasSame($now.setZone(tz), 'day')
  };
  const base = { lead_id: r.lead_id, cita_id: r.cita_id, paso: r.paso, secuencia: r.secuencia, ronda: r.ronda,
                 canal: r.canal, plantilla: r.plantilla, idioma: lang, origen: 'P34' };
  if (r.canal === 'email') {
    const e = EMAIL[lang][r.plantilla](v);
    return { json: { ...base, email: r.email, asunto: e.asunto, mensaje: e.mensaje, cta_texto: e.cta } };
  }
  return { json: { ...base, whatsapp: r.whatsapp, mensaje: WA[lang][r.plantilla](v), rol: 'assistant', off_topic: false, solo_registrar: false } };
});

// One row for Seguimientos per message, sent or failed (WhatsApp branch = output 0, email branch = output 1).
// Una fila en Seguimientos por mensaje, enviado o fallido (rama WhatsApp = salida 0, rama email = salida 1).
// Columns / Columnas: seguimiento_id, fecha, lead_id, origen, secuencia, ronda, paso, canal, mensaje, message_id, resultado, cita_id
const BRANCH = 0;   // 0 = WhatsApp (after P31e) · 1 = email (after P32c)
const msgs = $('Is WhatsApp?').all(BRANCH);
const rand = () => Math.random().toString(36).slice(2, 7).toUpperCase();
return $input.all().map((item, i) => {
  const t = msgs[i].json;
  const r = item.json || {};
  const fecha = r.fecha || $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
  const resultado = BRANCH === 0
    ? ((r.ok === false || r.estado_entrega === 'error') ? 'error: ' + (r.error || 'send_failed') : (r.estado_entrega || 'queued'))
    : (r.ok ? 'sent' : 'error: ' + (r.error || 'send_failed'));
  const mensaje = BRANCH === 0 ? t.mensaje : `${t.asunto}\n\n${t.mensaje}`;
  return { json: {
    row: ['SEG-' + fecha.slice(0, 10).replace(/-/g, '') + '-' + rand(), fecha, t.lead_id, 'P34', t.secuencia, t.ronda, t.paso,
          t.canal, mensaje, r.wa_message_sid || r.message_id || '', resultado, t.cita_id],
    cita_id: t.cita_id, paso: t.paso, canal: t.canal, resultado
  } };
});

// One row for Seguimientos per message, sent or failed (WhatsApp branch = output 0, email branch = output 1).
// Una fila en Seguimientos por mensaje, enviado o fallido (rama WhatsApp = salida 0, rama email = salida 1).
// Columns / Columnas: seguimiento_id, fecha, lead_id, origen, secuencia, ronda, paso, canal, mensaje, message_id, resultado, cita_id
const BRANCH = 1;   // 0 = WhatsApp (after P31e) · 1 = email (after P32c)
const msgs = $('Is WhatsApp?').all(BRANCH);
const rand = () => Math.random().toString(36).slice(2, 7).toUpperCase();
return $input.all().map((item, i) => {
  const t = msgs[i].json;
  const r = item.json || {};
  const fecha = r.fecha || $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
  const resultado = BRANCH === 0
    ? ((r.ok === false || r.estado_entrega === 'error') ? 'error: ' + (r.error || 'send_failed') : (r.estado_entrega || 'queued'))
    : (r.ok ? 'sent' : 'error: ' + (r.error || 'send_failed'));
  const mensaje = BRANCH === 0 ? t.mensaje : `${t.asunto}\n\n${t.mensaje}`;
  return { json: {
    row: ['SEG-' + fecha.slice(0, 10).replace(/-/g, '') + '-' + rand(), fecha, t.lead_id, 'P34', t.secuencia, t.ronda, t.paso,
          t.canal, mensaje, r.wa_message_sid || r.message_id || '', resultado, t.cita_id],
    cita_id: t.cita_id, paso: t.paso, canal: t.canal, resultado
  } };
});
